/// Encodes the remote read surface. A subclass owns transport, session translation and the
/// session lifecycle methods; every other call fails before any byte is sent.
abstract base class WireRepositorySessionCalls
    implements RepositorySessionCalls {
  /// Sends one read request and returns its decoded JSON result.
  Future<Object?> invokeRead(String method, Map<String, Object?> arguments);

  /// The helper's session for an application session identifier.
  BigInt helperSession(BigInt sessionId);

  /// The typed failure for a call the remote surface does not support.
  Never unsupported(String method);

